[Resource from github at repo://missingbulb/Claudinite/sha/ab7e003adbc1c66403bfda7c9e723216c68e0877/contents/engine/version.mjs] // THE ENGINE VERSION — the value that says which engine release a repo is running
// (docs/versioned-updates/DESIGN.md §2). The engine root vendors wholesale, so this
// module ships into every mount with the rest of the engine, and a member's stamp
// records the value it received (vendoring/apply-vendor-set.mjs). That pair is what
// makes "installed version → target version" answerable on the member side: which
// engine migrations still apply, and whether a pack's minimum is satisfied.
//
// DATE-ANCHORED, `<day>.<n>` — the shape, the ordering and why the corpus versions
// this way rather than in semver are stated below the constant. Every comparison made
// of this value is "installed < target" over a total order, so the format buys one
// thing over the plain counter it replaced: the version says when it was cut, without
// a second lookup.
//
// ADVANCED BY RELEASE, never by an ordinary change: a release is a snapshot that has
// passed the live canary rehearsal once (DESIGN §2.1), and the bump is what declares
// that happened. An engine migration is written against the version it lands in — it
// applies to repos below that value.
export const ENGINE_VERSION = '60823.1';

// THE VERSION FORMAT — how every engine and pack version in the corpus is written,
// read and ordered. The helpers below are imported by every side that creates a
// version (each `packs/*/pack.mjs`), stamps one (updates/), compares two (the update
// planners, the dashboard, the fleet roster) or scrapes one out of source text over
// the API. They live beside the constant rather than in a module of their own so the
// engine surface a member's mount must carry for any of it is one file.
//
// THE SHAPE IS `<day>.<n>` — `60820.1`, displayed with a leading `v`. The day part
// is `(year - 2020) * 10000 + month * 100 + day`, so 2026-08-20 is 60820; the second
// part is the running number of versions cut on that day, starting at 1. It is a
// STRING and never a float: `60820.10` and `60820.1` are different versions and the
// same number.
//
// Anchoring the year on 2020 rather than taking its last digit is what keeps the day
// part monotonic past 2029 — 2030 reads 100101, above every 2029 value, where a
// last-digit year would wrap to 0 and sort a decade of releases underneath.
//
// WHY DATE-ANCHORED AT ALL. Every comparison the update flows make is still
// "installed < target" over a total order — nothing here needs semver's three
// components. What the plain counter could not do is say WHEN: a member stamped at 6
// against a canon at 13 is behind by an unknown amount of time, and the fleet
// surfaces that as a number a reader has to go and date by hand.
//
// LEGACY TOLERANCE, until 2026-08-27 (#1106). Versions were plain positive integers
// until 2026-08-20, and the integers are still sitting in every member's stamp, in
// each pack's `minEngineVersion` floor and in every migration record's range. So a
// legacy integer parses here as `<n>.0` — below every date-anchored version, which
// is exactly where a member that has not re-stamped belongs. Dependency-free, like
// the manifest spec it serves.

// The day part of a Date, in UTC. Callers that have a `YYYY-MM-DD` string already
// (the corpus passes `today` around in that form) can hand it straight over.
export function versionDay(when = new Date()) {
  const d = typeof when === 'string' ? new Date(`${when.slice(0, 10)}T00:00:00Z`) : when;
  if (Number.isNaN(d.getTime())) return null;
  return (d.getUTCFullYear() - 2020) * 10000 + (d.getUTCMonth() + 1) * 100 + d.getUTCDate();
}

// A date-anchored version, as its two parts. The day part is at least five digits
// (2020-01-01 is 101, but nothing predates the scheme, and the smallest day a repo
// can carry is 60820), which is what keeps it unambiguously apart from a legacy
// counter — those never reached three figures.
const DATE_ANCHORED = /^([1-9]\d{4,5})\.([1-9]\d*)$/;

// A version in EITHER form, as `{ day, seq }`, or null when the value is not one.
// A legacy integer is `{ day: n, seq: 0 }` — the same tuple shape, so every
// comparison below is written once and knows nothing about the two spellings.
//
// ZERO IS READABLE and is not an absence: an install runs from version zero
// (docs/versioned-updates/DESIGN.md §3), so a stamp may hold one and it must sort
// below everything rather than read as "this stamp says nothing". Nothing may
// DECLARE it — that is `isDeclaredVersion` below.
export function parseVersion(v) {
  if (typeof v === 'number') return Number.isInteger(v) && v >= 0 ? { day: v, seq: 0 } : null;
  if (typeof v !== 'string') return null;
  const m = DATE_ANCHORED.exec(v.trim());
  return m ? { day: Number(m[1]), seq: Number(m[2]) } : null;
}

export const isVersion = (v) => parseVersion(v) !== null;

// What a manifest or a release may WRITE: a real version, never the install floor.
export const isDeclaredVersion = (v) => isVersion(v) && v !== 0;

// True for the retiring spelling only — the one thing the removal change (#1106)
// greps for, and what a reader needing to say "this predates the scheme" asks.
export const isLegacyVersion = (v) => typeof v === 'number' && Number.isInteger(v) && v >= 0;

// Order two versions: negative when `a` is older. An UNPARSEABLE version is not an
// error and not a zero — it sorts as equal to everything, so a caller that cannot
// price one side reports "no gap" rather than inventing one in either direction.
// Callers that must distinguish absence from equality check `isVersion` first.
export function compareVersions(a, b) {
  const x = parseVersion(a);
  const y = parseVersion(b);
  if (!x || !y) return 0;
  return x.day - y.day || x.seq - y.seq;
}

export const versionAbove = (a, b) => compareVersions(a, b) > 0;

// Equality has to ask more than `compareVersions(a, b) === 0`: an unpriceable side
// compares equal to everything, so the two versions must both be real ones first.
export const versionsEqual = (a, b) => isVersion(a) && isVersion(b) && compareVersions(a, b) === 0;

export const formatVersion = ({ day, seq }) => `${day}.${seq}`;

// The next version to cut today, given the one that stands. A new day restarts the
// running number at 1; a second version on the same day is `.2`. A `current` that is
// legacy, absent or unparseable simply does not constrain today's number — the day
// part is already above every integer the old scheme ever reached.
export function nextVersion(current, today = new Date()) {
  const day = versionDay(today);
  const held = parseVersion(current);
  return held && held.day === day ? `${day}.${held.seq + 1}` : `${day}.1`;
}

// The version-shaped fragment for the text scrapers — the readers that lift a
// version out of `engine/version.mjs` or a `pack.mjs` fetched over the API, where
// there is nothing to import. Kept here so the six of them cannot disagree about
// what a version looks like; each wraps it in its own anchor.
export const VERSION_SOURCE = String.raw`\d+(?:\.\d+)?`;

// What such a scraper should hand back: the literal as it was written, so a legacy
// integer stays a number and a date-anchored version stays a string, and every
// comparison downstream is the same one function.
export function versionFromLiteral(text) {
  if (text == null) return null;
  const t = String(text).trim();
  const v = t.includes('.') ? t : Number(t);
  return isVersion(v) ? v : null;
}

[Resource from github at repo://missingbulb/Claudinite/sha/ab7e003adbc1c66403bfda7c9e723216c68e0877/contents/packs/claudinite-tasks/tasks/verify-production/probes.mjs] // The coded production-validation grammar and judgment (#1530) — pure, no I/O.
// A verification issue states declarative PROBES on its first lines, each one
// URL and one assertion, in two classes with distinct failure meanings:
//
//   Live-probe:   <url> :: <assertion>   — the liveness gate. Any failing means
//                                          the release has not landed: the run
//                                          re-arms and comes back, and nothing
//                                          is judged.
//   Verify-probe: <url> :: <assertion>   — the verification itself, judged only
//                                          once every liveness probe passes. Any
//                                          failing is a real fault in production.
//
// Both classes are REQUIRED: without a liveness gate a verify failure cannot be
// told from a release that simply has not happened, and would reopen the
// original issue over nothing.
//
// Assertions, after the `::`:
//   status <n>                       the response code itself (the one op a
//                                    non-2xx response can pass)
//   [not ]contains <text>            body carries the literal text
//   [not ]matches /<re>/[flags]      body matches the JS regex
//   json <path> exists               dotted path resolves to a value
//   json <path> == <value>           strict-deep equality with the JSON value
//   json <path> != <value>           its negation
//   json <path> >= <value>           dotted identifiers compared segment-wise
//                                    numeric — '60821.10' is ten past '60821.3',
//                                    where floats and string order both lie

export const LIVE_FIELD = 'Live-probe';
export const VERIFY_FIELD = 'Verify-probe';
export const RETRY_FIELD = 'Retry-every';
export const ORIGINAL_FIELD = 'Original-issue';

const UNIT_MS = { minute: 60_000, hour: 3_600_000, day: 86_400_000, week: 7 * 86_400_000 };

// `<count> <unit>` and nothing else. Null for anything unreadable — absence is a
// problem the caller names, never a default cadence nobody chose.
export function parseRetryEvery(text) {
  const m = /^(\d+)\s*(minute|hour|day|week)s?$/i.exec(String(text ?? '').trim());
  return m ? Number(m[1]) * UNIT_MS[m[2].toLowerCase()] : null;
}

// One assertion, or null for a line that reads as none. Values after json ops are
// JSON literals; one that does not parse is taken as a bare string, so
// `== fleet` and `== "fleet"` assert the same thing.
export function parseAssertion(text) {
  const s = String(text ?? '').trim();
  let m;
  if ((m = /^status\s+(\d{3})$/.exec(s))) return { op: 'status', status: Number(m[1]) };
  if ((m = /^(not\s+)?contains\s+(.+)$/.exec(s))) {
    return { op: 'contains', negate: !!m[1], text: m[2] };
  }
  if ((m = /^(not\s+)?matches\s+\/(.*)\/([a-z]*)$/.exec(s))) {
    try {
      // Compiled here so an unreadable pattern is a parse problem, not a run crash.
      void new RegExp(m[2], m[3]);
    } catch { return null; }
    return { op: 'matches', negate: !!m[1], source: m[2], flags: m[3] };
  }
  if ((m = /^json\s+(\S+)\s+exists$/.exec(s))) return { op: 'json-exists', path: m[1] };
  if ((m = /^json\s+(\S+)\s+(==|!=|>=)\s+(.+)$/.exec(s))) {
    const raw = m[3].trim();
    let value;
    try { value = JSON.parse(raw); } catch { value = raw; }
    const op = { '==': 'json-eq', '!=': 'json-ne', '>=': 'json-gte' }[m[2]];
    return { op, path: m[1], value };
  }
  return null;
}

// Dotted identifiers compared segment-wise numeric, a missing segment counting
// zero. Kept string-typed end to end — '60820.10' and '60820.1' are different
// versions and the same float. A non-numeric segment falls back to string order
// for that segment.
export function compareDotted(a, b) {
  const as = String(a).split('.');
  const bs = String(b).split('.');
  for (let i = 0; i < Math.max(as.length, bs.length); i += 1) {
    const [x, y] = [as[i] ?? '0', bs[i] ?? '0'];
    const [nx, ny] = [Number(x), Number(y)];
    const cmp = Number.isNaN(nx) || Number.isNaN(ny)
      ? x.localeCompare(y)
      : nx - ny;
    if (cmp !== 0) return cmp < 0 ? -1 : 1;
  }
  return 0;
}

const dig = (value, path) => path.split('.').reduce(
  (v, seg) => (v !== null && typeof v === 'object' ? v[seg] : undefined), value);

const deepEq = (a, b) => JSON.stringify(a) === JSON.stringify(b);

// Judge one assertion against one response ({ status, body }). Returns
// { ok, observed } — the observation is what was actually read, which is the
// evidence half of every verdict this task reports.
export function evaluateAssertion(assertion, { status, body }) {
  if (assertion.op === 'status') {
    return { ok: status === assertion.status, observed: `HTTP ${status}` };
  }
  if (status < 200 || status >= 300) return { ok: false, observed: `HTTP ${status}` };
  if (assertion.op === 'contains') {
    const found = body.includes(assertion.text);
    return { ok: found !== assertion.negate, observed: found ? 'text present' : 'text absent' };
  }
  if (assertion.op === 'matches') {
    const found = new RegExp(assertion.source, assertion.flags).test(body);
    return { ok: found !== assertion.negate, observed: found ? 'pattern present' : 'pattern absent' };
  }
  // The json ops.
  let parsed;
  try { parsed = JSON.parse(body); } catch { return { ok: false, observed: 'body is not JSON' }; }
  const actual = dig(parsed, assertion.path);
  const observed = actual === undefined ? `${assertion.path} absent` : `read ${JSON.stringify(actual)}`;
  if (assertion.op === 'json-exists') return { ok: actual !== undefined, observed };
  if (actual === undefined) return { ok: assertion.op === 'json-ne', observed };
  if (assertion.op === 'json-eq') return { ok: deepEq(actual, assertion.value), observed };
  if (assertion.op === 'json-ne') return { ok: !deepEq(actual, assertion.value), observed };
  return { ok: compareDotted(actual, assertion.value) >= 0, observed };
}

// Parse a verification issue's human text into the spec the worker runs. Every
// gap or unreadable line is a PROBLEM by name — the item then parks with the
// list rather than half-running a spec that silently dropped a probe.
export function parseVerificationSpec(text) {
  const problems = [];
  const live = [];
  const verify = [];
  const probeRe = new RegExp(`^(${LIVE_FIELD}|${VERIFY_FIELD}):[ \\t]*(.*)$`, 'gm');
  for (const m of String(text ?? '').matchAll(probeRe)) {
    const [field, rest] = [m[1], m[2].trim()];
    const parts = /^(\S+)\s*::\s*(.+)$/.exec(rest);
    const url = parts?.[1] ?? null;
    const assertion = parts ? parseAssertion(parts[2]) : null;
    if (!url || !/^https?:\/\//.test(url) || !assertion) {
      problems.push(`unreadable ${field} line: \`${rest}\` — expected \`https://… :: <assertion>\``);
      continue;
    }
    (field === LIVE_FIELD ? live : verify).push({ url, assertion, raw: parts[2].trim() });
  }
  const originalIssue = (() => {
    const m = new RegExp(`^${ORIGINAL_FIELD}:[ \\t]*#?(\\d+)`, 'm').exec(String(text ?? ''));
    return m ? Number(m[1]) : null;
  })();
  const retryRaw = new RegExp(`^${RETRY_FIELD}:[ \\t]*(.+)$`, 'm').exec(String(text ?? ''))?.[1]?.trim() ?? null;
  const retryEveryMs = parseRetryEvery(retryRaw);

  if (!live.length) problems.push(`no ${LIVE_FIELD}: line — without a liveness gate, "not deployed yet" and "deployed and broken" are indistinguishable`);
  if (!verify.length) problems.push(`no ${VERIFY_FIELD}: line — nothing would be verified`);
  if (!originalIssue) problems.push(`no ${ORIGINAL_FIELD}: line — a failing verification would have nowhere to land`);
  if (!retryEveryMs) problems.push(`no readable ${RETRY_FIELD}: line — expected \`<count> <minutes|hours|days|weeks>\``);
  return { originalIssue, retryEveryMs, retryRaw, live, verify, problems };
}

// Run one probe class. Each URL is fetched ONCE however many probes read it;
// `fetchUrl(url)` resolves to { status, body } or throws, and a throw fails the
// probe with the error as its observation rather than the run.
export async function runProbes(probes, fetchUrl) {
  const responses = new Map();
  const results = [];
  for (const probe of probes) {
    if (!responses.has(probe.url)) {
      responses.set(probe.url, await fetchUrl(probe.url).catch((e) => ({ error: e.message })));
    }
    const response = responses.get(probe.url);
    results.push(response.error
      ? { probe, ok: false, observed: `fetch failed: ${response.error}` }
      : { probe, ...evaluateAssertion(probe.assertion, response) });
  }
  return results;
}

export const renderResult = ({ probe, ok, observed }) =>
  `${ok ? 'PASS' : 'FAIL'} — ${probe.url} :: ${probe.raw} — ${observed}`;

